"""A small finite-language regular expression synthesizer.

Strings are represented by Unicode units, optionally generalized to character
categories and repeated units.  The language is collected in a prefix
machine, equivalent suffix states are coalesced, and its paths are combined
using a regular-expression algebra.
"""
from dataclasses import dataclass, replace
from functools import lru_cache
import unicodedata


@dataclass
class Settings:
    digits: bool = False
    non_digits: bool = False
    spaces: bool = False
    non_spaces: bool = False
    words: bool = False
    non_words: bool = False
    escape: bool = False
    with_surrogates: bool = False
    repetitions: bool = False
    min_repetitions: int = 1
    min_substring_length: int = 1
    no_start_anchor: bool = False
    no_end_anchor: bool = False
    no_anchors: bool = False
    verbose: bool = False
    colorize: bool = False
    ignore_case: bool = False
    capture_groups: bool = False


@dataclass(frozen=True)
class Part:
    # A part is either a literal scalar or a shorthand character category.
    text: str
    category: bool = False


@dataclass(frozen=True)
class Unit:
    parts: tuple = ()
    children: tuple = ()
    minimum: int = 1
    maximum: int = 1

    def base(self):
        return Unit(self.parts, self.children)

    def repeated(self, minimum, maximum=None):
        return replace(self, minimum=minimum,
                       maximum=minimum if maximum is None else maximum)

    def key(self):
        if self.children:
            return ''.join(x.key() for x in self.children)
        return ''.join(p.text for p in self.parts)

    def class_char(self, settings):
        if (self.minimum == self.maximum == 1 and not self.children
                and len(self.parts) == 1 and not self.parts[0].category):
            c = self.parts[0].text
            if len(c) == 1 and not (settings.escape and ord(c) > 127):
                return c
        return None


SPACE_POINTS = frozenset([9, 10, 11, 12, 13, 32, 0x85, 0xa0, 0x1680,
                         *range(0x2000, 0x200b), 0x2028, 0x2029,
                         0x202f, 0x205f, 0x3000])


def is_space(c):
    return ord(c) in SPACE_POINTS


def is_word(c):
    cat = unicodedata.category(c)
    return (cat[0] in 'LM' or cat in ('Nd', 'Nl', 'Pc')
            or ord(c) in (0x200c, 0x200d)
            or 0x24b6 <= ord(c) <= 0x24e9
            or 0x1f130 <= ord(c) <= 0x1f149
            or 0x1f150 <= ord(c) <= 0x1f169
            or 0x1f170 <= ord(c) <= 0x1f189)


def lower_case(s):
    low = s.lower()
    # Some lower-case mappings expand a scalar into multiple scalars and
    # cannot stand for the original string in case-insensitive matching.
    return low if len(low) == len(s) else s


def hangul_kind(c):
    x = ord(c)
    if 0x1100 <= x <= 0x115f or 0xa960 <= x <= 0xa97c:
        return 'L'
    if 0x1160 <= x <= 0x11a7 or 0xd7b0 <= x <= 0xd7c6:
        return 'V'
    if 0x11a8 <= x <= 0x11ff or 0xd7cb <= x <= 0xd7fb:
        return 'T'
    if 0xac00 <= x <= 0xd7a3:
        return 'LV' if (x - 0xac00) % 28 == 0 else 'LVT'
    return ''


def split_units(s):
    """Split scalar sequences, preserving compound symbol units."""
    units = []
    regional_count = 0
    for c in s:
        cp = ord(c)
        regional = 0x1f1e6 <= cp <= 0x1f1ff
        join = False
        if units:
            prev = units[-1][-1]
            if regional and regional_count % 2 == 1:
                join = True
            elif 0x1f3fb <= cp <= 0x1f3ff:
                join = ord(prev) >= 0x2300
            else:
                a, b = hangul_kind(prev), hangul_kind(c)
                join = ((a == 'L' and b in ('L', 'V', 'LV', 'LVT'))
                        or (a in ('LV', 'V') and b in ('V', 'T'))
                        or (a in ('LVT', 'T') and b == 'T'))
        if join:
            units[-1] += c
        else:
            units.append(c)
        regional_count = regional_count + 1 if regional else 0
    return units


def convert_part(c, st):
    digit = unicodedata.category(c) == 'Nd'
    space = is_space(c)
    word = is_word(c)
    if st.digits and digit:
        return Part('\\d', True)
    if st.spaces and space:
        return Part('\\s', True)
    if st.words and word:
        return Part('\\w', True)
    if st.non_digits and not digit:
        return Part('\\D', True)
    if st.non_words and not word:
        return Part('\\W', True)
    if st.non_spaces and not space:
        return Part('\\S', True)
    return Part(c)


def tokenize(s, st):
    if st.ignore_case:
        s = lower_case(s)
    return tuple(Unit(tuple(convert_part(c, st) for c in u))
                 for u in split_units(s))


@lru_cache(maxsize=16384)
def is_primitive(unit):
    n = len(unit)
    for p in range(1, n // 2 + 1):
        if n % p == 0 and unit == unit[:p] * (n // p):
            return False
    return True


def find_at(haystack, needle, start):
    n = len(needle)
    first = needle[0]
    for i in range(start, len(haystack) - n + 1):
        if haystack[i] == first and haystack[i:i + n] == needle:
            return i
    return -1


def compress_repetitions(units, st):
    n = len(units)
    if n < 2:
        return units
    # Uniform strings are common (particularly after category conversion).
    if all(x == units[0] for x in units):
        if st.min_substring_length <= 1 and n > st.min_repetitions:
            return (units[0].repeated(n),)
        return units
    candidates = []
    seen = set()
    for a in range(n - 1):
        for width in range(1, (n - a) // 2 + 1):
            u = units[a:a + width]
            if u != units[a + width:a + 2 * width] or u in seen:
                continue
            seen.add(u)
            if not is_primitive(u):
                continue
            positions = []
            pos = 0
            while pos < n:
                pos = find_at(units, u, pos)
                if pos < 0:
                    break
                positions.append(pos)
                pos += width
            runs = []
            for pos in positions:
                if runs and runs[-1][1] == pos:
                    runs[-1][1] += width
                else:
                    runs.append([pos, pos + width])
            if width < st.min_substring_length:
                continue
            for start, end in runs:
                if (end - start) // width > st.min_repetitions:
                    candidates.append((end, -(end - start), width, start))
    candidates.sort(key=lambda x: (-x[0], x[1], x[2]))
    chosen = []
    cutoff = n
    for end, _, width, start in candidates:
        if end <= cutoff:
            chosen.append((start, end, width))
            cutoff = start
    out = []
    start = 0
    for a, b, width in reversed(chosen):
        out.extend(units[start:a])
        body = compress_repetitions(units[a:a + width], st)
        count = (b - a) // width
        unit = body[0] if len(body) == 1 else Unit(children=body)
        out.append(unit.repeated(count))
        start = b
    out.extend(units[start:])
    return tuple(out)


@dataclass(frozen=True)
class Expr:
    kind: str
    value: object = ()


EMPTY = Expr('literal', ())


def literal(units):
    return Expr('literal', tuple(units))


def concatenate(*expressions):
    parts = []
    for e in expressions:
        for p in e.value if e.kind == 'concat' else (e,):
            if p == EMPTY:
                continue
            if parts and parts[-1].kind == p.kind == 'literal':
                parts[-1] = literal(parts[-1].value + p.value)
            else:
                parts.append(p)
    if not parts:
        return EMPTY
    if len(parts) == 1:
        return parts[0]
    return Expr('concat', tuple(parts))


def expr_length(e):
    if e.kind == 'literal':
        return len(e.value)
    if e.kind == 'class':
        return 1
    if e.kind == 'concat':
        return sum(expr_length(p) for p in e.value)
    if e.kind == 'alt':
        return max(map(expr_length, e.value), default=0)
    if e.kind == 'optional':
        return expr_length(e.value)
    return 0


class Algebra:
    def __init__(self, settings):
        self.st = settings

    def optional(self, e):
        return Expr('optional', e)

    def union(self, a, b):
        if a == b:
            return a
        if a == EMPTY:
            return self.optional(b)
        if b == EMPTY:
            return self.optional(a)
        if a.kind == b.kind == 'literal':
            av, bv = a.value, b.value
            i = 0
            while i < min(len(av), len(bv)) and av[i] == bv[i]:
                i += 1
            if i:
                return concatenate(literal(av[:i]),
                                   self.union(literal(av[i:]), literal(bv[i:])))
            i = 0
            while i < min(len(av), len(bv)) and av[-i-1] == bv[-i-1]:
                i += 1
            if i:
                return concatenate(self.union(literal(av[:-i]), literal(bv[:-i])),
                                   literal(av[-i:]))
        def class_set(e):
            if e.kind == 'class':
                return e.value
            if e.kind == 'literal' and len(e.value) == 1:
                c = e.value[0].class_char(self.st)
                if c is not None:
                    return frozenset((c,))
            return None
        ac, bc = class_set(a), class_set(b)
        if ac is not None and bc is not None:
            return Expr('class', ac | bc)
        alternatives = (list(a.value) if a.kind == 'alt' else [a])
        alternatives += (list(b.value) if b.kind == 'alt' else [b])
        alternatives.sort(key=lambda x: -expr_length(x))
        alternatives = tuple(dict.fromkeys(alternatives))
        return Expr('alt', alternatives)


class State:
    def __init__(self, index):
        self.index = index
        self.final = False
        self.edges = {}


class Machine:
    def __init__(self, sequences, settings):
        self.st = settings
        self.algebra = Algebra(settings)
        nodes = [State(0)]
        def seqkey(seq):
            return (len(seq), tuple((u.key(), u.minimum, u.maximum) for u in seq))
        for seq in sorted(set(sequences), key=seqkey):
            n = nodes[0]
            for u in seq:
                if settings.repetitions:
                    match = next((old for old in n.edges
                                  if old.base() == u.base()
                                  and u.minimum >= old.minimum
                                  and u.minimum <= old.maximum + 1), None)
                    if match is not None:
                        child = n.edges.pop(match)
                        combined = match.repeated(match.minimum,
                                                  max(match.maximum, u.maximum))
                        n.edges[combined] = child
                        n = child
                        continue
                if u not in n.edges:
                    child = State(len(nodes))
                    nodes.append(child)
                    n.edges[u] = child
                n = n.edges[u]
            n.final = True
        registry = {}
        canonical = {}
        def minimize(n):
            edges = {c: minimize(d) for c, d in reversed(list(n.edges.items()))}
            signature = (n.final, frozenset((c, d.index) for c, d in edges.items()))
            rep = registry.get(signature)
            if rep is None:
                rep = n
                rep.edges = edges
                registry[signature] = rep
            canonical[n] = rep
            return rep
        self.start = minimize(nodes[0])
        states = set(canonical.values())
        max_indices = {n: max(o.index for o, c in canonical.items() if c is n)
                       for n in states}
        @lru_cache(None)
        def height(n):
            return max((height(d) + 1 for d in n.edges.values()), default=0)
        self.states = sorted(states, key=lambda n: (height(n), max_indices[n]))

    def expression(self):
        edges = {}
        for n in self.states:
            for u, d in reversed(list(n.edges.items())):
                key = n, d
                val = literal((u,))
                edges[key] = self.algebra.union(edges[key], val) if key in edges else val
        end = State(-1)
        for n in self.states:
            if n.final:
                edges[n, end] = EMPTY
        for n in self.states:
            if n is self.start:
                continue
            incoming = [(a, v) for (a, b), v in edges.items() if b is n]
            outgoing = [(b, v) for (a, b), v in edges.items() if a is n]
            for a, u in incoming:
                for b, v in outgoing:
                    key = a, b
                    new = concatenate(u, v)
                    edges[key] = self.algebra.union(edges[key], new) if key in edges else new
            edges = {key: val for key, val in edges.items() if n not in key}
        return edges.get((self.start, end), EMPTY)


class Renderer:
    COLORS = {'anchor': '1;33', 'group': '1;32', 'bar': '1;31',
              'class': '1;36', 'optional': '1;35', 'count': '104;37',
              'category': '103;30', 'flags': '40;93'}

    def __init__(self, settings):
        self.st = settings
        self.group_open = '(' if settings.capture_groups else '(?:'

    def color(self, text, category):
        if self.st.colorize:
            return '\x1b[' + self.COLORS[category] + 'm' + text + '\x1b[0m'
        return text

    def escape_char(self, c, in_class=False):
        controls = {'\t': r'\t', '\n': r'\n', '\r': r'\r', '\v': r'\v', '\f': r'\f'}
        if c in controls:
            return controls[c]
        if self.st.verbose:
            if c in ' #':
                return '\\' + c
            if is_space(c):
                return self.color('\\s', 'category')
        if self.st.escape and ord(c) > 127:
            cp = ord(c)
            if self.st.with_surrogates and cp > 0xffff:
                cp -= 0x10000
                return '\\u{' + format(0xd800 + (cp >> 10), 'x') + '}\\u{' + format(0xdc00 + (cp & 1023), 'x') + '}'
            return '\\u{' + format(cp, 'x') + '}'
        specials = '\\-[]^' if in_class else '\\-[]^$.|?*+(){}'
        return '\\' + c if c in specials else c

    def class_text(self, chars):
        chars = sorted(chars)
        content = []
        i = 0
        while i < len(chars):
            end = i + 1
            while end < len(chars) and ord(chars[end]) == ord(chars[end-1]) + 1:
                end += 1
            if end - i >= 3:
                content += [self.escape_char(chars[i], True), self.color('-', 'class'),
                            self.escape_char(chars[end-1], True)]
            else:
                content.extend(self.escape_char(c, True) for c in chars[i:end])
            i = end
        return self.color('[', 'class') + ''.join(content) + self.color(']', 'class')

    def unit_needs_group(self, u):
        if u.children:
            return True
        if len(u.parts) != 1:
            return True
        p = u.parts[0]
        return (not p.category and self.st.escape and self.st.with_surrogates
                and ord(p.text) > 0xffff)

    def unit_items(self, u):
        body = []
        if u.children:
            for child in u.children:
                body.extend(self.unit_items(child))
        else:
            for p in u.parts:
                text = self.color(p.text, 'category') if p.category else self.escape_char(p.text)
                body.append(('text', text))
        if u.minimum == u.maximum == 1:
            return body
        count = ('{' + str(u.minimum) + '}' if u.minimum == u.maximum else
                 '{' + str(u.minimum) + ',' + str(u.maximum) + '}')
        suffix = self.color(count, 'count')
        if self.unit_needs_group(u):
            return [('group', body, suffix)]
        return body + [('text', suffix)]

    def optional_needs_group(self, e):
        if e.kind != 'literal' or len(e.value) != 1:
            return True
        u = e.value[0]
        if u.children or u.minimum != 1 or u.maximum != 1 or len(u.parts) != 1:
            return True
        p = u.parts[0]
        return p.category or (self.st.escape and ord(p.text) > 127)

    def items(self, e, top=False):
        if e.kind == 'literal':
            out = []
            for u in e.value:
                out.extend(self.unit_items(u))
            return out
        if e.kind == 'class':
            return [('text', self.class_text(e.value))]
        if e.kind == 'concat':
            out = []
            for p in e.value:
                out.extend(self.items(p))
            return out
        if e.kind == 'optional':
            child = e.value
            if self.optional_needs_group(child):
                return [('group', self.items(child, top=True), self.color('?', 'optional'))]
            return self.items(child) + [('text', self.color('?', 'optional'))]
        if e.kind == 'alt':
            out = []
            for i, p in enumerate(e.value):
                if i:
                    out.append(('bar', self.color('|', 'bar')))
                out.extend(self.items(p))
            return out if top else [('group', out, '')]
        return []

    def compact_items(self, items):
        out = []
        for item in items:
            if item[0] == 'group':
                out.append(self.color(self.group_open, 'group'))
                out.append(self.compact_items(item[1]))
                out.append(self.color(')', 'group') + item[2])
            else:
                out.append(item[1])
        return ''.join(out)

    def verbose_items(self, items, indent=2):
        lines = []
        line = ''
        prefix = ' ' * indent
        def flush():
            nonlocal line
            if line:
                lines.append(prefix + line)
                line = ''
        for item in items:
            if item[0] == 'text':
                line += item[1]
            elif item[0] == 'bar':
                flush()
                lines.append(prefix + item[1])
            else:
                flush()
                lines.append(prefix + self.color(self.group_open, 'group'))
                lines.extend(self.verbose_items(item[1], indent + 2))
                lines.append(prefix + self.color(')', 'group') + item[2])
        flush()
        return lines

    def render(self, expression):
        st = self.st
        flags = ('i' if st.ignore_case else '') + ('x' if st.verbose else '')
        flags = self.color('(?' + flags + ')', 'flags') if flags else ''
        start = '' if st.no_anchors or st.no_start_anchor else self.color('^', 'anchor')
        end = '' if st.no_anchors or st.no_end_anchor else self.color('$', 'anchor')
        items = self.items(expression)
        if not st.verbose:
            return flags + start + self.compact_items(items) + end
        lines = [flags]
        if start:
            lines.append(start)
        lines.extend(self.verbose_items(items))
        if end:
            lines.append(end)
        return '\n'.join(lines)


def generate(strings, settings):
    nonempty = [s for s in strings if s != '']
    strings = nonempty or ['']
    sequences = []
    for s in strings:
        units = tokenize(s, settings)
        if settings.repetitions:
            units = compress_repetitions(units, settings)
        sequences.append(units)
    expression = Machine(sequences, settings).expression()
    return Renderer(settings).render(expression)
