"""Command-line entry point for the regular expression generator."""
import errno
import os
import re
import sys

from engine import Settings, generate
from help_text import SHORT_HELP, LONG_HELP

USAGE = 'Usage: grex [OPTIONS] {INPUT...|--file <FILE>}'
HINT = "For more information, try '--help'.\n"
SHORT = {
    'd': 'digits', 'D': 'non-digits', 's': 'spaces', 'S': 'non-spaces',
    'w': 'words', 'W': 'non-words', 'e': 'escape', 'r': 'repetitions',
    'x': 'verbose', 'c': 'colorize', 'i': 'ignore-case', 'g': 'capture-groups',
    'f': 'file', 'h': 'help', 'v': 'version',
}
LONG = set(SHORT.values()) | {
    'with-surrogates', 'min-repetitions', 'min-substring-length',
    'no-start-anchor', 'no-end-anchor', 'no-anchors',
}
VALUES = {'file': 'FILE', 'min-repetitions': 'QUANTITY',
          'min-substring-length': 'LENGTH'}


def fail(message, usage=True, status=2):
    sys.stderr.write('error: ' + message + '\n\n')
    if usage:
        sys.stderr.write(USAGE + '\n\n')
    sys.stderr.write(HINT)
    raise SystemExit(status)


def designation(name):
    return '--' + name + (' <' + VALUES[name] + '>' if name in VALUES else '')


def missing_value(name):
    fail("a value is required for '" + designation(name) +
         "' but none was supplied", usage=False)


def looks_like_option(arg):
    return arg.startswith('-') and arg != '-'


def short_options(arg):
    # A short-option cluster containing an unknown letter is a positional
    # test case, even if the first few letters are otherwise valid options.
    letters = []
    for i, c in enumerate(arg[1:], start=1):
        if c not in SHORT:
            return None
        name = SHORT[c]
        if name in VALUES:
            return letters + [(name, arg[i + 1:] or None)]
        letters.append((name, None))
    return letters


def parse(args):
    st = Settings()
    inputs = []
    seen = set()
    filename = None
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--':
            inputs.extend(args[i + 1:])
            break
        options = None
        long_form = arg.startswith('--')
        if long_form:
            raw = arg[2:]
            name, sep, val = raw.partition('=')
            if name in LONG:
                if name not in VALUES and sep:
                    fail("unexpected value '" + val + "' for '--" + name +
                         "' found; no more were expected")
                options = [(name, val if sep else None)]
        elif arg.startswith('-') and len(arg) > 1:
            options = short_options(arg)
        if options is None:
            inputs.extend(args[i:])
            break
        for name, value in options:
            if name in seen:
                fail("the argument '" + designation(name) +
                     "' cannot be used multiple times")
            seen.add(name)
            if name in VALUES:
                if value is None:
                    if i + 1 == len(args):
                        missing_value(name)
                    nextarg = args[i + 1]
                    if name == 'file' and looks_like_option(nextarg):
                        missing_value(name)
                    value = nextarg
                    i += 1
                if value == '':
                    missing_value(name)
                if name == 'file':
                    filename = value
                else:
                    if re.fullmatch(r'\+?[0-9]+', value) is None:
                        fail("invalid value '" + value + "' for '" + designation(name) +
                             "': Value is not a valid unsigned integer", usage=False)
                    number = int(value)
                    if number > 4294967295:
                        fail("invalid value '" + value + "' for '" + designation(name) +
                             "': Value is not a valid unsigned integer", usage=False)
                    if number == 0:
                        fail("invalid value '" + value + "' for '" + designation(name) +
                             "': Value must not be zero", usage=False)
                    setattr(st, name.replace('-', '_'), number)
            elif name == 'help':
                sys.stdout.write(LONG_HELP if long_form else SHORT_HELP)
                raise SystemExit(0)
            elif name == 'version':
                sys.stdout.write('grex 1.4.6\n')
                raise SystemExit(0)
            else:
                setattr(st, name.replace('-', '_'), True)
        i += 1
    if filename is not None and inputs:
        fail("the argument '--file <FILE>' cannot be used with '[INPUT]...'")
    required = []
    if st.with_surrogates and not st.escape:
        required.append('--escape')
    if filename is None and not inputs:
